// Generated by AI (UnitTest MCP)
//! ADR-0119 decision 5's Export workflow: a single request-then-receipt
//! flow (unlike Purge's two-phase preview/confirm) producing a bounded,
//! redacted representation for a named purpose. Tenant- and
//! repository-scoped like every other per-repository Administration route;
//! a request or receipt is only ever disclosed to the principal and
//! repository that made it.

use std::time::{SystemTime, UNIX_EPOCH};

use ackplane_server::administration_store::{
    ExportDataCategory, ExportOutcome, ExportReceipt, NewExportReceipt, NewExportRequest,
    MAX_EXPORT_RECORDS,
};
use ackplane_server::export_provider::{self, ExportProviderConfig, ExportProviderError};
use axum::{
    extract::{Path, State},
    http::StatusCode,
    Json,
};
use serde::{Deserialize, Serialize};

use super::{administration_error_status, AdministrationApiState};

#[derive(Deserialize)]
pub(super) struct ExportRequestBody {
    policy_id: String,
    /// Only `telemetry_events` today; see `ExportDataCategory`.
    data_category: String,
    purpose: String,
    max_records: u32,
    idempotency_key: String,
}

#[derive(Serialize)]
pub(super) struct ExportRequestResponse {
    request_id: String,
    idempotent_replay: bool,
    receipt: Option<ExportReceiptResponse>,
}

#[derive(Serialize)]
pub(super) struct ExportReceiptResponse {
    receipt_id: String,
    outcome: &'static str,
    reason: String,
    artifact_path: Option<String>,
    manifest_digest_hex: Option<String>,
    schema_version: String,
    record_count: Option<i64>,
    redacted_fields: Vec<String>,
    occurred_at_seconds: Option<u64>,
}

impl From<ExportReceipt> for ExportReceiptResponse {
    fn from(receipt: ExportReceipt) -> Self {
        Self {
            receipt_id: receipt.receipt_id,
            outcome: outcome_label(receipt.outcome),
            reason: receipt.reason,
            artifact_path: receipt.artifact_path,
            manifest_digest_hex: receipt.manifest_digest.map(hex_encode),
            schema_version: receipt.schema_version,
            record_count: receipt.record_count,
            redacted_fields: receipt.redacted_fields,
            occurred_at_seconds: unix_seconds(receipt.occurred_at),
        }
    }
}

/// Requests, then synchronously executes, a bounded/redacted Export.
/// Mirrors `request_platform_snapshot`'s synchronous-v1 shape: a request
/// either completes with a `succeeded`/`failed` receipt before the response
/// returns, or is refused before any request row exists (no active policy).
pub(super) async fn request_export(
    State(state): State<AdministrationApiState>,
    Path(repository_id): Path<String>,
    Json(request): Json<ExportRequestBody>,
) -> Result<Json<ExportRequestResponse>, StatusCode> {
    let Some(export_config) = state.export.clone() else {
        return Err(StatusCode::SERVICE_UNAVAILABLE);
    };
    let data_category =
        parse_data_category(&request.data_category).ok_or(StatusCode::BAD_REQUEST)?;
    if request.max_records == 0 || request.max_records > MAX_EXPORT_RECORDS {
        return Err(StatusCode::BAD_REQUEST);
    }
    let now = SystemTime::now();
    let new_request = NewExportRequest {
        policy_id: request.policy_id,
        requested_by: state.tenant_id.to_string(),
        tenant_id: state.tenant_id.to_string(),
        repository_id: repository_id.clone(),
        data_category,
        purpose: request.purpose,
        max_records: request.max_records,
        idempotency_key: request.idempotency_key,
    };

    let outcome = {
        let mut administration = state.administration.lock().await;
        administration
            .request_export(&new_request, now)
            .await
            .map_err(administration_error_status)?
    };

    // A replay of a request that already has a receipt must return that
    // receipt again, not query and write the artifact a second time.
    let existing_receipt = {
        let mut administration = state.administration.lock().await;
        administration
            .export_receipt_for_request(&outcome.request.request_id)
            .await
            .map_err(administration_error_status)?
    };
    if let Some(receipt) = existing_receipt {
        return Ok(Json(ExportRequestResponse {
            request_id: outcome.request.request_id,
            idempotent_replay: true,
            receipt: Some(receipt.into()),
        }));
    }

    let receipt = execute_and_record_export(
        &state,
        &export_config,
        &outcome.request.request_id,
        &repository_id,
        &outcome.request.purpose,
        outcome.request.max_records,
    )
    .await?;
    Ok(Json(ExportRequestResponse {
        request_id: outcome.request.request_id,
        idempotent_replay: outcome.idempotent_replay,
        receipt: Some(receipt.into()),
    }))
}

async fn execute_and_record_export(
    state: &AdministrationApiState,
    export_config: &ExportProviderConfig,
    request_id: &str,
    repository_id: &str,
    purpose: &str,
    max_records: u32,
) -> Result<ExportReceipt, StatusCode> {
    let now = SystemTime::now();
    let new_receipt = match export_provider::create_telemetry_export(
        export_config,
        request_id,
        state.tenant_id.as_ref(),
        repository_id,
        purpose,
        max_records,
    )
    .await
    {
        Ok(artifact) => NewExportReceipt {
            request_id: request_id.to_string(),
            outcome: ExportOutcome::Succeeded,
            reason: "The bounded, redacted export completed.".to_string(),
            artifact_path: Some(artifact.artifact_path),
            manifest_digest: Some(artifact.manifest_digest),
            schema_version: export_provider::TELEMETRY_EXPORT_SCHEMA_VERSION.to_string(),
            record_count: Some(artifact.record_count),
            redacted_fields: artifact.redacted_fields,
            occurred_at: now,
        },
        Err(error) => {
            tracing::error!(%error, "Bridge Export execution failed");
            NewExportReceipt {
                request_id: request_id.to_string(),
                outcome: ExportOutcome::Failed,
                reason: export_error_reason(&error),
                artifact_path: None,
                manifest_digest: None,
                schema_version: export_provider::TELEMETRY_EXPORT_SCHEMA_VERSION.to_string(),
                record_count: None,
                redacted_fields: Vec::new(),
                occurred_at: now,
            }
        }
    };

    let mut administration = state.administration.lock().await;
    administration
        .record_export_receipt(&new_receipt, now)
        .await
        .map_err(administration_error_status)
}

pub(super) async fn export_receipt(
    State(state): State<AdministrationApiState>,
    Path((repository_id, request_id)): Path<(String, String)>,
) -> Result<Json<ExportReceiptResponse>, StatusCode> {
    let mut administration = state.administration.lock().await;
    // The request itself names its `requested_by` principal and
    // `repository_id`; only the tenant and repository that made it may read
    // the receipt, mirroring every other Snapshot/purge ownership check.
    let request = administration
        .export_request(&request_id)
        .await
        .map_err(administration_error_status)?
        .ok_or(StatusCode::NOT_FOUND)?;
    if request.requested_by != state.tenant_id.as_ref() || request.repository_id != repository_id {
        return Err(StatusCode::NOT_FOUND);
    }
    let receipt = administration
        .export_receipt_for_request(&request_id)
        .await
        .map_err(administration_error_status)?
        .ok_or(StatusCode::NOT_FOUND)?;
    Ok(Json(receipt.into()))
}

fn export_error_reason(error: &ExportProviderError) -> String {
    match error {
        ExportProviderError::Io(_) => {
            "the export directory or artifact could not be prepared.".to_string()
        }
        ExportProviderError::Database(_) => {
            "the export query against the data category failed.".to_string()
        }
    }
}

fn parse_data_category(value: &str) -> Option<ExportDataCategory> {
    match value {
        "telemetry_events" => Some(ExportDataCategory::TelemetryEvents),
        _ => None,
    }
}

fn outcome_label(outcome: ExportOutcome) -> &'static str {
    match outcome {
        ExportOutcome::Succeeded => "succeeded",
        ExportOutcome::Failed => "failed",
        ExportOutcome::Refused => "refused",
    }
}

fn hex_encode(bytes: Vec<u8>) -> String {
    bytes.iter().map(|byte| format!("{byte:02x}")).collect()
}

fn unix_seconds(timestamp: SystemTime) -> Option<u64> {
    timestamp
        .duration_since(UNIX_EPOCH)
        .ok()
        .map(|duration| duration.as_secs())
}

